      const disallowed = /\b(?:on|for)\s+(?:this|the|current)\s+page\b|\bcurrent\s+page\b|\bvisible\s+(?:items?|listings?)\b|\b(?:items?|listings?)\s+(?:shown|visible)\b|\bpage\s+(?:items?|listings?)\b/i;
