          const pendingLeaseActive = Boolean((pendingLease?.token || pendingLease?.owner) && Number(pendingLease.expiresAt) > Date.now());
          const pendingHandoffActive = pendingHandoff?.status === 'running' && pendingHandoff.handoffToken
