          gm: ctx.scope.GM, namespace: ADS_TOOL_ID, doc,
          info: { name: 'Etsy Automation Tools · Ads Keyword Manager', version: ctx.engines.adsKeywordManagerVersion },
          resources: { makaytronLogo: ctx.assets?.logo ?? '' },
