  // ── src/ui/text.js ──
  const __eat_ui_text = (() => {
    // One translator for the drawer, the workspace and the setup.
    //
    // Only English, the source text, is bundled in full. Every other language
    // reads its downloaded pack (core/language-packs.js); until the pack is there,
    // the first-screen strings come from strings-picker.js (bundled for every
    // language) and everything else falls back to English.

    const { UI_STRINGS } = __eat_ui_strings;
    const { WORKSPACE_STRINGS, UI_LANGUAGES } = __eat_ui_strings_workspace;
    const { PICKER_STRINGS } = __eat_ui_strings_picker;
    const { detectLanguage, interpolate, textDirection } = __eat_core_i18n;
    const { packText } = __eat_core_language_packs;

    const LANGS = UI_LANGUAGES.map((l) => l.code);

    // Browser tags that name a language we offer under another code.
    const ALIASES = Object.freeze({ no: 'nb', nn: 'nb', tl: 'fil', iw: 'he', in: 'id' });
    const TRADITIONAL_CHINESE = /^zh-(?:TW|HK|MO|Hant)/i;

    /** Maps browser language tags onto the codes of our packs before matching. */
    function normalizeTags(tags) {
      return (Array.isArray(tags) ? tags : [tags]).filter((tag) => typeof tag === 'string').map((tag) => {
        if (TRADITIONAL_CHINESE.test(tag)) return 'zh-TW';
        if (/^zh(?:-|$)/i.test(tag)) return 'zh-CN';
        const base = tag.split('-')[0].toLowerCase();
        return ALIASES[base] ?? tag;
      });
    }

    /**
     * @param {object} o
     * @param {object} o.settings
     * @param {object} o.scope
     * @param {object} [o.packs] core/language-packs.js instance; without it only bundled text is used
     */
    function createText({ settings, scope, packs = null }) {
      const listeners = new Set();
      const language = () => {
        const chosen = settings.get().language;
        return chosen && LANGS.includes(chosen) ? chosen : detectLanguage(normalizeTags(scope.navigator?.languages ?? []), LANGS, 'en');
      };
      const t = (key, vars) => {
        const lang = language();
        const text = UI_STRINGS[lang]?.[key] ?? WORKSPACE_STRINGS[lang]?.[key] ?? packText(lang, key) ?? PICKER_STRINGS[lang]?.[key]
          ?? UI_STRINGS.en[key] ?? WORKSPACE_STRINGS.en[key] ?? key;
        return interpolate(text, vars);
      };
      /** State of the current language's pack: bundled, idle, loading, ready or error. */
      const pack = () => (packs ? packs.state(language()) : { status: 'bundled' });
      /** Starts the download of the current language's pack if it is needed. */
      const ensurePack = () => (packs ? packs.ensure(language()) : Promise.resolve(pack()));
      const retryPack = () => (packs ? packs.retry(language()) : Promise.resolve(pack()));
      const onPackChange = (fn) => { listeners.add(fn); return () => listeners.delete(fn); };
      const packChanged = () => { for (const fn of [...listeners]) fn(); };
      /** The same for any language: used to download a new language before switching to it. */
      const languageState = (code) => (packs ? packs.state(code) : { status: 'bundled' });
      const ensureLanguage = (code) => (packs ? (packs.state(code).status === 'error' ? packs.retry(code) : packs.ensure(code)) : Promise.resolve({ status: 'bundled' }));
      const packSize = (code) => packs?.size?.(code) ?? 0;
      return { t, language, direction: () => textDirection(language()), pack, ensurePack, retryPack, onPackChange, packChanged, languageState, ensureLanguage, packSize };
    }

    /** A language's own name ("Türkçe", "Deutsch"), as the language list shows it. */
    function languageName(code) {
      return UI_LANGUAGES.find((l) => l.code === code)?.name ?? code;
    }
    return Object.freeze({ normalizeTags, createText, languageName });
  })();

  // ── src/ui/toasts.js ──
  const __eat_ui_toasts = (() => {
    // Toasts for notices announced while the page is open (design canvas artboard
    // States: success, error and info toasts with a timer line). The notice itself
    // stays in the bell's list; the toast only says it as it happens.
    // Design sources: Toast-01 anatomy as adapted in the canvas (.toast/.in/.ico/.pl).

    const { h, icon } = __eat_ui_dom;
    const { ICONS } = __eat_ui_icons;

    const SHOW_MS = 6000;
    const TONE = { seriesDone: 'ok', scanDone: 'ok', seriesStopped: 'err', autopilotWaiting: 'info', queueWaiting: 'info', newMessage: 'info', newVersion: 'info' };
    const STYLE = {
      ok: { glyph: ICONS.check, well: 'background: #ecfdf3; color: #15803d;' },
      err: { glyph: ICONS.alert, well: 'background: #fef2f2; color: #b91c1c;' },
      info: { glyph: ICONS.info, well: 'background: var(--soft); color: var(--ink2);' },
    };

    /** Watches `notices` and shows a toast for each notice added after it starts. */
    function createToasts({ doc, container, text, notices, now = () => Date.now() }) {
      if (!notices) return () => {};
      const since = now();
      const shown = new Set(notices.list().map((n) => n.id));
      let stack = null;

      function show(n) {
        if (!stack?.isConnected) {
          stack = h(doc, 'div', { class: 'col', role: 'region', 'aria-live': 'polite', 'aria-label': text.t('nt.title'), style: 'position: fixed; inset-inline-end: 16px; bottom: 16px; gap: 8px; z-index: 2147483646;' });
          container.append(stack);
        }
        const tone = TONE[n.event] ?? 'info';
        const { glyph, well } = STYLE[tone];
        const remove = () => el.remove();
        const el = h(doc, 'div', { class: 'toast', role: tone === 'err' ? 'alert' : 'status', 'data-notice': n.id },
          h(doc, 'div', { class: 'in' },
            h(doc, 'span', { class: 'ico', style: well }, icon(doc, glyph, 14)),
            h(doc, 'span', { class: 'col grow', style: 'gap: 2px; min-width: 0;' },
              h(doc, 'span', { class: 'sm b', text: n.title }),
              n.detail ? h(doc, 'span', { class: 'xs mute', text: n.detail }) : null),
            h(doc, 'button', { class: 'ib', type: 'button', 'aria-label': text.t('fb.cancel'), onclick: remove }, icon(doc, ICONS.close, 14))),
          h(doc, 'div', { class: 'pl', style: `animation: eat-toast-timer ${SHOW_MS}ms linear forwards;` }));
        stack.append(el);
        doc.defaultView?.setTimeout(remove, SHOW_MS);
      }

      return notices.subscribe((items) => {
        for (const n of items) {
          if (shown.has(n.id)) continue;
          shown.add(n.id);
          if (n.at >= since) show(n);
        }
      });
    }
    return Object.freeze({ createToasts });
  })();

